use super::*;
use crate::cli;

fn tmp() -> std::path::PathBuf {
    let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos();
    let d = std::env::temp_dir().join(format!("bsc-memory-test-{nanos}"));
    std::fs::create_dir_all(&d).unwrap();
    d
}

fn store_memories(store: &bsc_json_store::Store) -> Vec<Memory> {
    // `list()` returns record BODIES, not ids — deserialize each directly.
    store.list().into_iter().filter_map(|r| serde_json::from_str::<Memory>(&r).ok()).collect()
}

fn mem(id: &str, ms: i64, tags: &[&str], status: &str, horizon: &str, links: &[(&str, &str)]) -> Memory {
    Memory {
        id: id.into(),
        text: id.into(),
        tags: tags.iter().map(|s| s.to_string()).collect(),
        created_at_ms: ms,
        status: status.into(),
        horizon: horizon.into(),
        kind: KIND_NOTE.into(),
        links: links.iter().map(|(rel, t)| Link::new(*t, *rel)).collect(),
    }
}

#[test]
fn parse_tags_lowercases_and_parse_link_specs_types_the_edges() {
    assert_eq!(parse_tags("RF, network ,, rf"), vec!["rf", "network"]);
    // typed rel:ref, a bare ref -> related, case preserved on the ref, de-duped by (rel, ref).
    let links = parse_link_specs("about:bsc-graph--Methods.rs, some-plan-Ref, about:bsc-graph--Methods.rs, supersedes:old");
    assert_eq!(
        links,
        vec![
            Link::new("bsc-graph--Methods.rs", "about"),
            Link::new("some-plan-Ref", "related"),
            Link::new("old", "supersedes"),
        ]
    );
    // an empty rel or empty target degrades to a plain related link on the whole item, not a panic.
    assert_eq!(parse_link_specs(":x"), vec![Link::new(":x", "related")]);
}

#[test]
fn filter_and_order_narrows_on_every_facet_newest_first() {
    let items = vec![
        mem("1", 100, &["rf"], "open", HORIZON_NOW, &[("about", "2")]),
        mem("2", 300, &["net"], "done", HORIZON_FUTURE, &[]),
        mem("3", 200, &["rf"], "open", HORIZON_NOW, &[("supersedes", "1")]),
    ];
    let ids = |v: Vec<&Memory>| v.iter().map(|m| m.id.clone()).collect::<Vec<_>>();
    assert_eq!(ids(filter_and_order(&items, &Filter::default())), vec!["2", "3", "1"], "newest first");
    assert_eq!(ids(filter_and_order(&items, &Filter { tag: Some("RF"), ..Default::default() })), vec!["3", "1"]);
    assert_eq!(filter_and_order(&items, &Filter { status: Some("open"), ..Default::default() }).len(), 2);
    assert_eq!(ids(filter_and_order(&items, &Filter { horizon: Some("future"), ..Default::default() })), vec!["2"]);
    assert_eq!(ids(filter_and_order(&items, &Filter { link: Some("1"), ..Default::default() })), vec!["3"]);
    assert_eq!(ids(filter_and_order(&items, &Filter { rel: Some("about"), ..Default::default() })), vec!["1"]);
}

#[test]
fn store_list_yields_bodies_not_ids() {
    let dir = tmp();
    let d = dir.to_string_lossy().into_owned();
    for text in ["first", "second"] {
        cli::run(vec!["add".into(), text.into(), "--dir".into(), d.clone()], "bsc memory").expect("add");
    }
    let store = bsc_json_store::Store::new(dir, "memory");
    let raw = store.list();
    assert_eq!(raw.len(), 2);
    assert!(raw.iter().all(|r| r.trim_start().starts_with('{')), "bodies, not ids");
    assert_eq!(store_memories(&store).len(), 2);
}

#[test]
fn add_defaults_now_future_flag_sets_future_and_done_flips_status() {
    let dir = tmp();
    let d = dir.to_string_lossy().into_owned();
    cli::run(
        vec!["add".into(), "grounded finding".into(), "--tag".into(), "network".into(), "--dir".into(), d.clone()],
        "bsc memory",
    )
    .expect("add now");
    cli::run(
        vec!["add".into(), "a hope for the future".into(), "--future".into(), "--dir".into(), d.clone()],
        "bsc memory",
    )
    .expect("add future");

    let store = bsc_json_store::Store::new(dir, "memory");
    let items = store_memories(&store);
    let now = items.iter().find(|m| m.text.contains("grounded")).unwrap();
    let future = items.iter().find(|m| m.text.contains("hope")).unwrap();
    assert_eq!(now.horizon, HORIZON_NOW, "default horizon is now");
    assert_eq!(future.horizon, HORIZON_FUTURE, "--future marks it future");

    cli::run(vec!["done".into(), now.id.clone(), "--dir".into(), d.clone()], "bsc memory").expect("done");
    let after = store_memories(&store);
    assert_eq!(after.iter().find(|m| m.text.contains("grounded")).unwrap().status, "done");
    // horizon verb reclassifies without touching status
    cli::run(vec!["horizon".into(), future.id.clone(), "now".into(), "--dir".into(), d], "bsc memory").expect("reclass");
    assert_eq!(store_memories(&store).iter().find(|m| m.text.contains("hope")).unwrap().horizon, HORIZON_NOW);
}

#[test]
fn link_verb_adds_typed_edges_and_neighbors_traverses_both_directions() {
    let dir = tmp();
    let d = dir.to_string_lossy().into_owned();
    cli::run(vec!["add".into(), "root".into(), "--dir".into(), d.clone()], "bsc memory").expect("a");
    let a = store_memories(&bsc_json_store::Store::new(dir.clone(), "memory"))[0].id.clone();
    // b is added already pointing at a, with a typed edge.
    cli::run(vec!["add".into(), "follow".into(), "--link".into(), format!("because:{a}"), "--dir".into(), d.clone()], "bsc memory")
        .expect("b");
    let store = bsc_json_store::Store::new(dir.clone(), "memory");
    let b = store_memories(&store).into_iter().find(|m| m.id != a).unwrap().id;

    // link verb: one rel over several refs, de-duplicated.
    cli::run(
        vec!["link".into(), a.clone(), "about".into(), b.clone(), b.clone(), "bsc-graph--methods.rs".into(), "--dir".into(), d.clone()],
        "bsc memory",
    )
    .expect("link");
    let a_mem = store_memories(&store).into_iter().find(|m| m.id == a).unwrap();
    assert_eq!(
        a_mem.links,
        vec![Link::new(b.clone(), "about"), Link::new("bsc-graph--methods.rs", "about")],
        "typed, appended once, de-duplicated"
    );

    // neighbors of a: outgoing `about` edges, plus the incoming `because` edge from b.
    let items = store_memories(&store);
    let a_mem = items.iter().find(|m| m.id == a).unwrap();
    assert!(a_mem.has_rel("about") && a_mem.links_to(&b));
    let incoming: Vec<(&str, &str)> = items
        .iter()
        .filter(|m| m.id != a)
        .flat_map(|m| m.links.iter().filter(|l| l.target == a).map(move |l| (l.rel.as_str(), m.id.as_str())))
        .collect();
    assert_eq!(incoming, vec![("because", b.as_str())], "b -because-> a");
}

#[test]
fn a_legacy_bare_string_link_and_missing_horizon_still_read() {
    // A record written before typed edges / the horizon facet: links are bare strings, no horizon field.
    let legacy = r#"{"id":"9","text":"old","tags":[],"created_at_ms":1,"status":"open","links":["some-id","other"]}"#;
    let m: Memory = serde_json::from_str(legacy).expect("legacy record deserializes");
    assert_eq!(m.horizon, HORIZON_NOW, "absent horizon defaults to now");
    // An absent kind reads as UNCLASSIFIED, never as one of the real kinds. The 20 memories written
    // before this facet must not silently become lessons.
    assert_eq!(m.kind, KIND_NOTE, "absent kind defaults to note");
    assert_eq!(m.links, vec![Link::new("some-id", "related"), Link::new("other", "related")], "bare links -> related");
}

