fn kmem(id: &str, ms: i64, kind: &str, horizon: &str, status: &str, links: &[(&str, &str)]) -> Memory {
    Memory {
        id: id.into(),
        text: format!("text of {id}"),
        tags: vec![],
        created_at_ms: ms,
        status: status.into(),
        horizon: horizon.into(),
        kind: kind.into(),
        links: links.iter().map(|(rel, t)| Link::new(*t, *rel)).collect(),
    }
}

#[test]
fn brief_inlines_lessons_and_related_highlights_and_only_points_at_record_notes() {
    let refs = vec!["bsc-graph--methods.rs".to_string(), "feature:auth".to_string()];
    let items = vec![
        kmem("l1", 10, "lesson", "now", "open", &[("about", "bsc-graph--methods.rs")]),
        kmem("h1", 9, "highlight", "now", "open", &[("about", "feature:auth")]),
        kmem("r1", 8, "record", "now", "open", &[("about", "bsc-graph--methods.rs")]),
        kmem("r2", 7, "record", "now", "open", &[("about", "bsc-graph--methods.rs")]),
        kmem("a1", 6, "ambient", "now", "open", &[("about", "bsc-graph--methods.rs")]),
        kmem("n1", 5, "note", "now", "open", &[("about", "bsc-graph--methods.rs")]),
        kmem("other", 4, "lesson", "now", "open", &[("about", "something-else.rs")]),
    ];
    let b = crate::brief::brief(&items, &refs);
    let ids: Vec<&str> = b.about_this_work.iter().map(|m| m.id.as_str()).collect();
    assert_eq!(ids, vec!["l1", "h1"], "lessons and highlights edged to a ref, newest first");
    // A record note is the highest-precision memory a worker can get AND the most numerous once the
    // comment harvest lands, so it is counted and reached by command — never quoted into the block.
    assert_eq!(b.record_notes, 2);
    let rendered = crate::brief::render(&b, &refs);
    assert!(!rendered.contains("text of r1"), "a record note must not be inlined");
    // An unpromoted ambient capture is noise, and `note` means unreviewed. Neither may reach a session.
    assert!(!rendered.contains("text of a1"), "ambient never reaches a session");
    assert!(!rendered.contains("text of n1"), "unclassified never reaches a session");
    // …and a memory about a node this session does not touch is not its business.
    assert!(!rendered.contains("text of other"));
}

#[test]
fn brief_excludes_a_hope_and_an_already_handled_memory_from_what_is_inlined() {
    let refs = vec!["x.rs".to_string()];
    let items = vec![
        kmem("future", 10, "highlight", "future", "open", &[("about", "x.rs")]),
        kmem("done", 9, "lesson", "now", "done", &[("about", "x.rs")]),
        kmem("live", 8, "lesson", "now", "open", &[("about", "x.rs")]),
    ];
    let b = crate::brief::brief(&items, &refs);
    let ids: Vec<&str> = b.about_this_work.iter().map(|m| m.id.as_str()).collect();
    // A block headed "what we remember" must not mix a HOPE into what is known, and `done` means the
    // memory was acted on or folded elsewhere.
    assert_eq!(ids, vec!["live"]);
    assert_eq!(b.not_shown, 2, "the two excluded are still COUNTED, so nothing vanishes silently");
}

#[test]
fn standing_lessons_are_the_unlinked_ones_and_yield_their_budget_to_the_specific_half() {
    let refs = vec!["x.rs".to_string()];
    let mut items = vec![kmem("scoped", 100, "lesson", "now", "open", &[("about", "x.rs")])];
    // An unlinked lesson is one nobody scoped to anything, which is what makes it general.
    for i in 0..10 {
        items.push(kmem(&format!("standing{i}"), 90 - i, "lesson", "now", "open", &[]));
    }
    // An unlinked HIGHLIGHT is not a standing lesson — a decision nobody scoped is not a general trap.
    items.push(kmem("loose-highlight", 50, "highlight", "now", "open", &[]));

    let b = crate::brief::brief(&items, &refs);
    assert_eq!(b.about_this_work.len(), 1);
    assert!(b.standing.iter().all(|m| m.links.is_empty() && m.is_kind("lesson")));
    assert!(!b.standing.iter().any(|m| m.id == "loose-highlight"));
    assert!(b.standing.len() <= crate::brief::MAX_STANDING, "standing lessons are capped");
    assert!(b.about_this_work.len() + b.standing.len() <= crate::brief::MAX_INLINE);
}

#[test]
fn the_session_specific_half_keeps_its_budget_first() {
    // The cap exists because a block nobody finishes reading has injected nothing. When it binds, the
    // half that is ABOUT THIS WORK must survive — the standing lessons are the ride-along.
    let refs = vec!["x.rs".to_string()];
    let mut items: Vec<Memory> = (0..30)
        .map(|i| kmem(&format!("rel{i}"), 100 - i, "lesson", "now", "open", &[("about", "x.rs")]))
        .collect();
    for i in 0..5 {
        items.push(kmem(&format!("standing{i}"), 10 - i, "lesson", "now", "open", &[]));
    }
    let b = crate::brief::brief(&items, &refs);
    assert_eq!(b.about_this_work.len(), crate::brief::MAX_INLINE);
    assert!(b.standing.is_empty(), "no room left, and the specific half is what must survive");
    assert_eq!(b.not_shown, 30 - crate::brief::MAX_INLINE, "the rest are counted, not dropped");
}

#[test]
fn an_empty_brief_still_renders_a_block_that_says_it_is_empty() {
    // The defect this exists to avoid is `inject_required_algorithms`'s original one: a stream that
    // resolved to no feature was indistinguishable from a feature that required nothing, in SILENCE.
    // "Nothing is recorded" and "nobody looked" are different facts.
    let refs = vec!["untouched.rs".to_string()];
    let b = crate::brief::brief(&[], &refs);
    assert!(b.is_empty());
    let out = crate::brief::render(&b, &refs);
    assert!(out.contains(crate::brief::MARKER), "the block is still headed");
    assert!(out.contains("Nothing is recorded"), "it says so in words");
    assert!(out.contains("bsc memory add"), "and names the verb that fills it");
}

#[test]
fn every_block_carries_the_live_command_and_the_snapshot_warning() {
    let refs = vec!["x.rs".to_string()];
    let items = vec![kmem("l", 1, "lesson", "now", "open", &[("about", "x.rs")])];
    let out = crate::brief::render(&crate::brief::brief(&items, &refs), &refs);
    // Inlining is a COPY of a live store, which the worker protocol otherwise forbids. It is allowed
    // because a memory IS a snapshot — so the block must SAY that and hand over the live query.
    assert!(out.contains("SNAPSHOT"), "the block states what it is");
    assert!(out.contains("bsc memory list --link x.rs"), "and prints the command for the live answer");
    assert_eq!(crate::brief::command(&refs), "bsc memory list --link x.rs");
}

